   200	  return result;
   201	}
   202	
   203	export function openCodeUsageEvent(
   204	  partValue: unknown,
   205	): ObserveBatchEvent | null {
   206	  const part = object(partValue),
   207	    tokens = object(part?.tokens),
   208	    cache = object(tokens?.cache);
   209	  if (
   210	    part?.type !== "step-finish" ||
   211	    !id(part.sessionID) ||
   212	    !id(part.id) ||
   213	    !id(part.messageID) ||
   214	    !tokens
   215	  )
   216	    return null;
   217	  const result = event(
   218	    "opencode",
   219	    "opencode.step_finish.v1",
   220	    part.sessionID,
   221	    part.id,
   222	  );
   223	  const attrs = result.attrs!;
   224	  counter(attrs, "uncached_input_tokens", tokens.input);
   225	  counter(attrs, "cache_read_input_tokens", cache?.read);
   226	  counter(attrs, "cache_write_input_tokens", cache?.write);
   227	  counter(attrs, "reported_output_tokens", tokens.output);
   228	  counter(attrs, "reasoning_output_tokens", tokens.reasoning);
   229	  summedInput(attrs);
   230	  // Output/reasoning overlap changed across OpenCode versions. Keep raw output separate.
   231	  return result;
   232	}
   233	
   234	export interface UsageCollection {
   235	  events: ObserveBatchEvent[];
   236	  status: "partial" | "unavailable";
   237	  limited: boolean;
   238	  malformed: number;
   239	}
   240	
   241	/** Read only the explicitly supplied regular file, retaining a bounded tail.
   242	 * No cursor: later Stop hooks can retry failed writes and delayed transcript flushes.
   243	 * Even a complete file scan cannot establish complete provider or subagent coverage.
   244	 */
   245	export function collectTranscriptUsage(
   246	  path: string,
   247	  host: "claude-code" | "codex",
   248	  session: string,
   249	  limits: { maxBytes?: number; maxEvents?: number } = {},
   250	): UsageCollection {
   251	  const result: UsageCollection = {
   252	    events: [],
   253	    status: "unavailable",
   254	    limited: false,
   255	    malformed: 0,
   256	  };
   257	  if (!isAbsolute(path) || !id(session)) return result;
   258	  const maxBytes = Math.min(
   259	    4 * 1024 * 1024,
   260	    Math.max(1, Math.floor(limits.maxBytes ?? 4 * 1024 * 1024)),
   261	  );
   262	  const maxEvents = Math.min(
   263	    1000,
   264	    Math.max(1, Math.floor(limits.maxEvents ?? 1000)),
   265	  );
   266	  let fd: number | undefined;
   267	  try {
   268	    if (!statSync(path).isFile()) return result;
   269	    fd = openSync(path, constants.O_RDONLY | (constants.O_NONBLOCK ?? 0));
   270	    const stat = fstatSync(fd);
   271	    if (!stat.isFile()) return result;
   272	    const start = Math.max(0, stat.size - maxBytes);
   273	    const buffer = Buffer.alloc(Math.min(stat.size, maxBytes));
   274	    const bytes = readSync(fd, buffer, 0, buffer.length, start);
   275	    let text = buffer.subarray(0, bytes).toString("utf8");
   276	    result.limited = start > 0 || bytes !== buffer.length;
   277	    if (start > 0) {
   278	      const previous = Buffer.alloc(1);
   279	      readSync(fd, previous, 0, 1, start - 1);
   280	      if (previous[0] !== 10) {
   281	        const boundary = text.indexOf("\n");
   282	        text = boundary < 0 ? "" : text.slice(boundary + 1);
   283	      }
   284	    }
   285	    const end = text.lastIndexOf("\n");
   286	    if (end !== text.length - 1) result.limited = true;
   287	    text = end < 0 ? "" : text.slice(0, end);
   288	    const lines = text.split("\n");
   289	    result.status = "partial";
   290	    for (let i = lines.length - 1; i >= 0; i--) {
   291	      if (!lines[i].trim()) continue;
   292	      try {
   293	        const row: unknown = JSON.parse(lines[i]);
   294	        const next =
   295	          host === "codex"
   296	            ? codexUsageEvent(row, session)
   297	            : claudeUsageEvent(row, session);
   298	        if (next) {
   299	          if (result.events.length === maxEvents) {
   300	            result.limited = true;
   301	            break;
   302	          }
   303	          result.events.push(next);
   304	        }
   305	      } catch {
   306	        result.malformed++;
   307	      }
   308	    }
   309	    result.events.reverse();
   310	  } catch {
   311	    /* Missing, unreadable or unsupported source stays unavailable. */
   312	  } finally {
   313	    if (fd !== undefined) closeSync(fd);
   314	  }
   315	  return result;
   316	}
   317	
   318	/** Acknowledged batch only: older CLI fallback cannot preserve source timestamps. */
   319	export function recordModelUsage(
   320	  binary: string,
   321	  cwd: string,
   322	  events: ObserveBatchEvent[],
   323	): boolean {
   324	  if (!events.length) return true;
   325	  try {
   326	    const output = execFileSync(binary, ["observe", "record", "--stdin"], {
   327	      cwd,
   328	      input: events.map((e) => JSON.stringify(e)).join("\n") + "\n",
   329	      timeout: 10000,
   330	      stdio: ["pipe", "pipe", "pipe"],
   331	    }).toString();
   332	    const ack = /^Recorded (\d+) event\(s\)(?:, skipped (\d+))?\s*$/i.exec(
   333	      output.trim(),
   334	    );
   335	    return (
   336	      ack !== null &&
   337	      Number(ack[1]) === events.length &&
   338	      Number(ack[2] ?? 0) === 0
   339	    );
   340	  } catch (error) {
   341	    debug(
   342	      "model-usage",
   343	      `Usage batch was not acknowledged: ${error instanceof Error ? error.name : "error"}`,
   344	    );
   345	    return false;
   346	  }
   347	}
   348	
   349	/** Keep repeated part broadcasts cheap; durable dedup/conflict handling is in Go. */
   350	export function createOpenCodeUsageRecorder(
   351	  write = recordModelUsage,
   352	): (binary: string, cwd: string, part: unknown) => void {
   353	  const acknowledged = new Set<string>();
   354	  return (binary, cwd, part) => {
   355	    const next = openCodeUsageEvent(part);
   356	    if (!next) return;
   357	    const fingerprint = JSON.stringify([cwd, next]);
   358	    if (acknowledged.has(fingerprint) || !write(binary, cwd, [next])) return;
   359	    acknowledged.add(fingerprint);
   360	    if (acknowledged.size > 1024)
   361	      acknowledged.delete(acknowledged.values().next().value!);
   362	  };
   363	}
"}

{"chunk_id":"b93d5a","wall_time_seconds":0.00000254,"exit_code":0,"original_token_count":1486,"output":"     1	#!/usr/bin/env node
     2	/**
     3	 * Session Summary Hook (Stop)
     4	 *
     5	 * Captures a session summary from the transcript when a session ends.
     6	 * Includes files modified, tools used, user tasks, and git commits.
     7	 *
     8	 * Storage:
     9	 * - Uses `aide memory add` with category=session
    10	 */
    11	
    12	import { debug, setDebugCwd } from "../lib/logger.js";
    13	import {
    14	  readStdin,
    15	  emitHookResult,
    16	  installHookSafetyNet,
    17	  findAideBinary,
    18	  detectPlatform,
    19	} from "../lib/hook-utils.js";
    20	import {
    21	  collectTranscriptUsage,
    22	  recordModelUsage,
    23	} from "../core/model-usage.js";
    24	import { setSessionContext } from "../lib/anchor.js";
    25	import {
    26	  buildSessionSummary,
    27	  getSessionCommits,
    28	  storeSessionSummary,
    29	} from "../core/session-summary-logic.js";
    30	import { getScopedState } from "../core/aide-client.js";
    31	import {
    32	  gatherPartials,
    33	  buildSummaryFromPartials,
    34	  cleanupPartials,
    35	} from "../core/partial-memory.js";
    36	
    37	const SOURCE = "session-summary";
    38	
    39	interface HookInput {
    40	  hook_event_name: string;
    41	  session_id: string;
    42	  cwd: string;
    43	  transcript_path?: string;
    44	  stop_hook_active?: boolean;
    45	}
    46	
    47	/**
    48	 * Generate and store a final session summary.
    49	 *
    50	 * Uses partials (if available) to enrich the transcript-based summary.
    51	 * After storing the final summary, cleans up all partials for this session
    52	 * by tagging them as "forget".
    53	 */
    54	function captureSessionSummary(
    55	  cwd: string,
    56	  sessionId: string,
    57	  transcriptPath: string,
    58	): boolean {
    59	  const binary = findAideBinary(cwd, sessionId);
    60	  if (!binary) {
    61	    debug(SOURCE, "aide binary not found, cannot capture session summary");
    62	    return false;
    63	  }
    64	
    65	  // Try to build the richest possible summary:
    66	  // 1. Gather partials from this session
    67	  // 2. Build from transcript (Claude Code has this)
    68	  // 3. Merge partials data with transcript summary
    69	  const partials = gatherPartials(binary, cwd, sessionId);
    70	  let summary: string | null = null;
    71	
    72	  if (partials.length > 0) {
    73	    // Build from partials + git data, scoped to this session's start time
    74	    // (session-scoped startedAt; falls back to "4 hours ago" inside
    75	    // getSessionCommits when the session never recorded one).
    76	    const startedAt = getScopedState(binary, cwd, sessionId, "startedAt");
    77	    const commits = getSessionCommits(cwd, startedAt ?? undefined);
    78	    summary = buildSummaryFromPartials(partials, commits, []);
    79	    debug(SOURCE, `Built summary from ${partials.length} partials`);
    80	  }
    81	
    82	  // Fall back to transcript-based summary if partials didn't produce enough
    83	  if (!summary) {
    84	    summary = buildSessionSummary(transcriptPath, cwd);
    85	  }
    86	
    87	  if (!summary) {
    88	    debug(SOURCE, "No summary generated (insufficient activity or transcript)");
    89	    // Still clean up partials even if no summary was generated
    90	    if (partials.length > 0) {
    91	      cleanupPartials(binary, cwd, sessionId);
    92	    }
    93	    return false;
    94	  }
    95	
    96	  const stored = storeSessionSummary(binary, cwd, sessionId, summary);
    97	  if (stored) {
    98	    debug(SOURCE, `Stored final session summary for ${sessionId.slice(0, 8)}`);
    99	    // Clean up partials now that the final summary is stored
   100	    const cleaned = cleanupPartials(binary, cwd, sessionId);
   101	    debug(SOURCE, `Cleaned up ${cleaned} partials after final summary`);
   102	  } else {
   103	    debug(SOURCE, "Failed to store session summary");
   104	  }
   105	  return stored;
   106	}
   107	
   108	async function main(): Promise<void> {
   109	  try {
   110	    const input = await readStdin();
   111	    if (!input.trim()) {
   112	      emitHookResult({ continue: true });
   113	      return;
   114	    }
   115	
   116	    const data: HookInput = JSON.parse(input);
   117	    const cwd = data.cwd || process.cwd();
   118	    const sessionId = data.session_id || "unknown";
   119	    setSessionContext(sessionId);
   120	
   121	    setDebugCwd(cwd);
   122	    debug(SOURCE, `Hook triggered: ${data.hook_event_name}`);
   123	
   124	    // For Stop hook, capture session summary
   125	    if (data.hook_event_name === "Stop" && data.transcript_path) {
   126	      // The transcript is an explicitly supplied source, not a discovery path.
   127	      // Stop can precede its flush; every scan remains partial coverage.
   128	      const binary = findAideBinary(cwd, sessionId);
   129	      if (binary) {
   130	        const usage = collectTranscriptUsage(
   131	          data.transcript_path,
   132	          detectPlatform(),
   133	          sessionId,
   134	        );
   135	        recordModelUsage(binary, cwd, usage.events);
   136	        debug(
   137	          SOURCE,
   138	          `Usage scan: ${usage.status}; limited=${usage.limited}; malformed=${usage.malformed}; records=${usage.events.length}`,
   139	        );
   140	      }
   141	      // Don't capture if stop hook is already active (avoid recursion)
   142	      if (!data.stop_hook_active) {
   143	        debug(SOURCE, "Stop hook - capturing session summary");
   144	        captureSessionSummary(cwd, sessionId, data.transcript_path);
   145	      }
   146	    }
   147	
   148	    emitHookResult({ continue: true });
   149	  } catch (err) {
   150	    debug(SOURCE, `Error: ${err}`);
   151	    emitHookResult({ continue: true });
   152	  }
   153	}
   154	
   155	installHookSafetyNet(SOURCE);
   156	
   157	main();
"}

