   289	// cmdObserveRecord emits observe events from the CLI: one event from
   290	// flags, or a batch of JSON Lines from stdin with --stdin. Used by hooks
   291	// (skill-injector, session-start) to record per-source injection events.
   292	func cmdObserveRecord(dbPath string, args []string) error {
   293		if hasFlag(args, "--stdin") {
   294			return cmdObserveRecordBatch(dbPath)
   295		}
   296		kind := parseFlag(args, "--kind=")
   297		name := parseFlag(args, "--name=")
   298		if kind == "" || name == "" {
   299			return fmt.Errorf("--kind and --name are required")
   300		}
   301		ev := &observe.Event{
   302			Kind:      observe.Kind(kind),
   303			Name:      name,
   304			Category:  parseFlag(args, "--category="),
   305			Subtype:   parseFlag(args, "--subtype="),
   306			FilePath:  parseFlag(args, "--file="),
   307			SessionID: parseFlag(args, "--session="),
   308			Error:     parseFlag(args, "--error="),
   309		}
   310		tokens, err := parseIntFlag(args, "--tokens=", ev.Tokens)
   311		if err != nil {
   312			return err
   313		}
   314		ev.Tokens = tokens
   315		saved, err := parseIntFlag(args, "--saved=", ev.TokensSaved)
   316		if err != nil {
   317			return err
   318		}
   319		ev.TokensSaved = saved
   320		for _, a := range args {
   321			if !strings.HasPrefix(a, "--attr=") {
   322				continue
   323			}
   324			kv := strings.SplitN(strings.TrimPrefix(a, "--attr="), "=", 2)
   325			if len(kv) == 2 {
   326				if ev.Attrs == nil {
   327					ev.Attrs = map[string]string{}
   328				}
   329				ev.Attrs[kv[0]] = kv[1]
   330			}
   331		}
   332	
   333		backend, err := NewBackend(dbPath)
   334		if err != nil {
   335			return err
   336		}
   337		defer backend.Close()
   338		return backend.Store().AddObserveEvent(ev)
