   372		type toolStats struct {
   373			Calls          int `json:"calls"`
   374			Counterfactual int `json:"counterfactual_tokens"`
   375			Actual         int `json:"actual_tokens"`
   376			Saved          int `json:"saved_tokens"`
   377		}
   378		byTool := map[string]*toolStats{}
   379		var total toolStats
   380	
   381		for _, e := range events {
   382			b, ok := byTool[e.Name]
   383			if !ok {
   384				b = &toolStats{}
   385				byTool[e.Name] = b
   386			}
   387			b.Calls++
   388			b.Actual += e.Tokens
   389			b.Saved += e.TokensSaved
   390			b.Counterfactual += e.Tokens + e.TokensSaved
   391			total.Calls++
   392			total.Actual += e.Tokens
   393			total.Saved += e.TokensSaved
   394			total.Counterfactual += e.Tokens + e.TokensSaved
   395		}
   396	
   397		if jsonOut {
   398			enc := json.NewEncoder(os.Stdout)
   399			enc.SetIndent("", "  ")
   400			return enc.Encode(map[string]any{
   401				"since":   filter.Since,
   402				"total":   total,
   403				"by_tool": byTool,
   404			})
   405		}
   406	
   407		if total.Calls == 0 {
   408			fmt.Println("No consume events recorded yet.")
   409			fmt.Println("Run some MCP code tools (code_outline, code_read_symbol) or file Reads to populate.")
   410			return nil
   411		}
   412	
   413		fmt.Println("Token efficiency")
   414		fmt.Println("================")
   415		fmt.Println()
   416		fmt.Println("Estimates use calibrated per-language char/token ratios")
   417		fmt.Println("(see pkg/code/tokens.go — measured against Anthropic count_tokens).")
   418		fmt.Println()
   419		fmt.Printf("Would have read:  %s tokens  (if every call had been a raw Read)\n", fmtInt(total.Counterfactual))
   420		fmt.Printf("Actually read:    %s tokens\n", fmtInt(total.Actual))
   421		fmt.Printf("Saved:            %s tokens", fmtInt(total.Saved))
   422		if total.Counterfactual > 0 {
   423			ratio := float64(total.Saved) / float64(total.Counterfactual) * 100
   424			fmt.Printf("  (%.1f%% efficiency)", ratio)
   425		}
   426		fmt.Println()
   427		fmt.Println()
   428	
   429		// Per-tool table
   430		names := make([]string, 0, len(byTool))
   431		for n := range byTool {
   432			names = append(names, n)
   433		}
   434		sort.Slice(names, func(i, j int) bool { return byTool[names[i]].Saved > byTool[names[j]].Saved })
   435	
   436		fmt.Printf("%-20s %6s  %14s  %14s  %14s  %6s\n", "tool", "calls", "would have", "actual", "saved", "eff")
   437		for _, n := range names {
   438			b := byTool[n]
   439			eff := ""
   440			if b.Counterfactual > 0 {
   441				eff = fmt.Sprintf("%.1f%%", float64(b.Saved)/float64(b.Counterfactual)*100)
   442			}
   443			fmt.Printf("%-20s %6d  %14s  %14s  %14s  %6s\n",
   444				n, b.Calls, fmtInt(b.Counterfactual), fmtInt(b.Actual), fmtInt(b.Saved), eff)
   445		}
   446		return nil
   447	}
