   330	// metaKeyTokensMigrated is set in BucketMeta once MigrateTokenEventsToObserve
   331	// completes successfully so subsequent daemon starts skip the migration.
   332	const metaKeyTokensMigrated = "schema.tokens_migrated_to_observe"
   333	
   334	// MigrateTokenEventsToObserve drains every entry from the legacy
   335	// BucketTokenEvents into BucketObserveEvents (translated) and clears the
   336	// legacy bucket. Idempotent: subsequent calls are no-ops once the meta flag
   337	// is set. Atomic per-batch within a single bbolt transaction so a crash mid-
   338	// migration leaves a recoverable state.
   339	//
   340	// Returns the number of events migrated on this call.
   341	func (s *BoltStore) MigrateTokenEventsToObserve() (int, error) {
   342		if v, _ := s.GetMeta(metaKeyTokensMigrated); v == "1" {
   343			return 0, nil
   344		}
   345		migrated := 0
   346		err := s.db.Update(func(tx *bolt.Tx) error {
   347			legacy := tx.Bucket(BucketTokenEvents)
   348			obs := tx.Bucket(BucketObserveEvents)
   349			if legacy == nil || obs == nil {
   350				return nil
   351			}
   352			var keys [][]byte
   353			err := legacy.ForEach(func(k, v []byte) error {
   354				var t memory.TokenEvent
   355				if err := json.Unmarshal(v, &t); err != nil {
   356					keys = append(keys, append([]byte{}, k...))
   357					return nil
   358				}
   359				ev := tokenEventToObserve(&t)
   360				if ev == nil {
   361					keys = append(keys, append([]byte{}, k...))
   362					return nil
   363				}
   364				data, err := json.Marshal(ev)
   365				if err != nil {
   366					return err
   367				}
   368				if err := obs.Put([]byte(ev.ID), data); err != nil {
   369					return err
   370				}
   371				keys = append(keys, append([]byte{}, k...))
   372				migrated++
   373				return nil
   374			})
   375			if err != nil {
   376				return err
   377			}
   378			for _, k := range keys {
   379				if err := legacy.Delete(k); err != nil {
   380					return err
   381				}
   382			}
   383			meta := tx.Bucket(BucketMeta)
   384			if meta != nil {
   385				return meta.Put([]byte(metaKeyTokensMigrated), []byte("1"))
   386			}
   387			return nil
   388		})
   389		return migrated, err
   390	}
