   202	// CleanupTokenEvents removes events older than maxAge. Returns the count of deleted events.
   203	func (s *BoltStore) CleanupTokenEvents(maxAge time.Duration) (int, error) {
   204		if maxAge <= 0 {
   205			return 0, nil // 0 (or less) disables pruning: retain token events forever
   206		}
   207		cutoff := time.Now().Add(-maxAge)
   208		var keysToDelete [][]byte
   209	
   210		err := s.db.View(func(tx *bolt.Tx) error {
   211			b := tx.Bucket(BucketTokenEvents)
   212			return b.ForEach(func(k, v []byte) error {
   213				var e memory.TokenEvent
   214				if err := json.Unmarshal(v, &e); err != nil {
   215					// Delete malformed entries too
   216					keysToDelete = append(keysToDelete, append([]byte{}, k...))
   217					return nil
   218				}
   219				if e.Timestamp.Before(cutoff) {
   220					keysToDelete = append(keysToDelete, append([]byte{}, k...))
   221				}
   222				return nil
   223			})
   224		})
   225		if err != nil {
   226			return 0, err
   227		}
   228	
   229		if len(keysToDelete) == 0 {
   230			return 0, nil
   231		}
   232	
   233		var count int
   234		err = s.db.Update(func(tx *bolt.Tx) error {
   235			b := tx.Bucket(BucketTokenEvents)
   236			for _, k := range keysToDelete {
   237				if err := b.Delete(k); err != nil {
   238					return err
   239				}
   240				count++
   241			}
   242			return nil
   243		})
   244		return count, err
