    28	}
    29	
    30	// TokenAccounting is additive to the legacy statistics. Stages must not be
    31	// summed: server and host observations can describe the same unjoined call.
    32	type TokenAccounting struct {
    33		ModelUsage      *TokenModelUsage          `json:"model_usage,omitempty"`
    34		Work            *TokenWork                `json:"work,omitempty"`
    35		Retrievals      *TokenRetrievals          `json:"retrievals,omitempty"`
    36		Transformations *TokenTransformations     `json:"transformations,omitempty"`
    37		Activity        *TokenActivity            `json:"activity,omitempty"`
    38		Version         int                       `json:"version"`
    39		Estimator       string                    `json:"estimator"`
    40		ByStage         map[string]*TokenQuantity `json:"by_stage"`
    41		Arguments       TokenQuantity             `json:"arguments"`
    42		LegacyEvents    int                       `json:"legacy_events"`
    43		MissingPayload  int                       `json:"missing_payload"`
    44		MissingIdentity int                       `json:"missing_identity"`
    45	}
    46	
    47	const TextEstimator = "utf8-bytes/3-v1"
    48	
    49	// MeasuredBytes preserves known zero and rejects malformed or negative sizes.
    50	func MeasuredBytes(attrs map[string]string, key string) (int64, bool) {
    51		if attrs["accounting_version"] != "1" {
    52			return 0, false
    53		}
    54		n, err := strconv.ParseInt(attrs[key], 10, 64)
    55		return n, err == nil && n >= 0 && n <= 1<<53-1
    56	}
    57	
    58	func EstimateTextTokens(bytes int64) int64 { return bytes/3 + (bytes%3+1)/3 }
    59	
    60	func NewTokenAccounting() *TokenAccounting {
    61		return &TokenAccounting{Version: 1, Estimator: TextEstimator, ByStage: make(map[string]*TokenQuantity), Transformations: NewTokenTransformations()}
    62	}
    63	
    64	func HasObservationIdentity(session string, attrs map[string]string) bool {
    65		return session != "" && attrs["host"] != "" && attrs["actor_id"] != "" &&
    66			attrs["invocation_id"] != "" && attrs["observation_stage"] != ""
    67	}
    68	
    69	func (a *TokenAccounting) Add(e *TokenEvent) {
    70		if e.EventType == "transformation" {
    71			if a.Transformations == nil {
    72				a.Transformations = NewTokenTransformations()
    73			}
    74			a.Transformations.Add(e)
    75			return
    76		}
    77		if !HasObservationIdentity(e.SessionID, e.Attrs) {
    78			a.MissingIdentity++
    79		}
    80		if e.Attrs["accounting_version"] != "1" {
    81			a.LegacyEvents++
    82			return
    83		}
    84		stage := e.Attrs["observation_stage"]
    85		if e.EventType == TokenEventContextInjected {
    86			// Prepared context sources are neither tool results nor generated
    87			// tool arguments. Source excerpts need not cover the output envelope.
    88			if n, ok := MeasuredBytes(e.Attrs, "payload_bytes"); ok && stage == "aide_context" {
    89				q := a.ByStage[stage]
    90				if q == nil {
    91					q = &TokenQuantity{}
    92					a.ByStage[stage] = q
    93				}
    94				q.Bytes += n
    95				q.EstimatedTokens += EstimateTextTokens(n)
    96				q.Events++
    97			} else {
    98				a.MissingPayload++
    99			}
   100			return
   101		}
   102		if n, ok := MeasuredBytes(e.Attrs, "payload_bytes"); ok && (stage == "host_result" || stage == "server_result") {
   103			q := a.ByStage[stage]
   104			if q == nil {
   105				q = &TokenQuantity{}
   106				a.ByStage[stage] = q
   107			}
   108			q.Bytes += n
   109			q.EstimatedTokens += EstimateTextTokens(n)
   110			q.Events++
   111		} else {
